from __future__ import annotations

"""Spotify audio-features needed for harmonic mixing.

The ``key`` is an integer pitch class using standard pitch-class notation:
0 = C, 1 = C#/Db, ... 11 = B. A value of ``-1`` means **no key was detected**
(the track is effectively atonal for matching purposes). ``mode`` is 1 for major
and 0 for minor. Pitch classes live on a 12-note circle, so 11 (B) sits right
next to 0 (C).
"""

from dataclasses import dataclass

NO_KEY = -1
MIN_KEY = 0
MAX_KEY = 11

MODE_MINOR = 0
MODE_MAJOR = 1


@dataclass(frozen=True)
class AudioFeatures:
    track_id: str
    key: int
    mode: int
    tempo: float
    energy: float = 0.5

    def __post_init__(self) -> None:
        if not self.track_id.strip():
            raise ValueError("track_id is required")
        if self.key != NO_KEY and not (MIN_KEY <= self.key <= MAX_KEY):
            raise ValueError("key must be -1 (no key) or 0..11")
        if self.mode not in (MODE_MINOR, MODE_MAJOR):
            raise ValueError("mode must be 0 (minor) or 1 (major)")
        if self.tempo <= 0:
            raise ValueError("tempo must be positive")
        if not (0.0 <= self.energy <= 1.0):
            raise ValueError("energy must be in [0, 1]")

    def has_detected_key(self) -> bool:
        return self.key != NO_KEY

    def is_major(self) -> bool:
        return self.mode == MODE_MAJOR

    @classmethod
    def from_raw(cls, raw: dict) -> "AudioFeatures":
        return cls(
            track_id=str(raw.get("id") or raw.get("track_id") or ""),
            key=int(raw.get("key", NO_KEY)),
            mode=int(raw.get("mode", MODE_MAJOR)),
            tempo=float(raw.get("tempo", 120.0)),
            energy=float(raw.get("energy", 0.5)),
        )


    def same_key_and_mode(self, other: "AudioFeatures") -> bool:
        return self.key == other.key and self.mode == other.mode

    def tempo_delta(self, other: "AudioFeatures") -> float:
        return abs(self.tempo - other.tempo)

    def as_dict(self) -> dict[str, object]:
        return {
            "track_id": self.track_id,
            "key": self.key,
            "mode": self.mode,
            "tempo": self.tempo,
            "energy": self.energy,
        }


def build_features(
    track_id: str,
    key: int,
    mode: int = MODE_MAJOR,
    tempo: float = 120.0,
    energy: float = 0.5,
) -> AudioFeatures:
    return AudioFeatures(track_id=track_id, key=key, mode=mode, tempo=tempo, energy=energy)


def parse_many(raws: list[dict]) -> list[AudioFeatures]:
    return [AudioFeatures.from_raw(raw) for raw in raws]


def with_detected_key(features: list[AudioFeatures]) -> list[AudioFeatures]:
    return [f for f in features if f.has_detected_key()]

