from __future__ import annotations

"""Human-readable key labels and Camelot-wheel codes.

DJs read keys off the Camelot wheel (1A..12B) rather than raw pitch classes.
These helpers turn an ``(key, mode)`` pair into display labels and are used to
annotate match results. A track with no detected key has no label.
"""

from audio_features import AudioFeatures, MODE_MAJOR, NO_KEY

KEY_NAMES = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]

# Camelot number for each pitch class in major (B side) and minor (A side).
_CAMELOT_MAJOR = {0: 8, 1: 3, 2: 10, 3: 5, 4: 12, 5: 7, 6: 2, 7: 9, 8: 4, 9: 11, 10: 6, 11: 1}
_CAMELOT_MINOR = {0: 5, 1: 12, 2: 7, 3: 2, 4: 9, 5: 4, 6: 11, 7: 6, 8: 1, 9: 8, 10: 3, 11: 10}


def is_atonal(key: int) -> bool:
    return key == NO_KEY


def key_name(key: int) -> str | None:
    if is_atonal(key):
        return None
    return KEY_NAMES[key]


def camelot_code(key: int, mode: int) -> str | None:
    if is_atonal(key):
        return None
    if mode == MODE_MAJOR:
        return f"{_CAMELOT_MAJOR[key]}B"
    return f"{_CAMELOT_MINOR[key]}A"


def label_for(features: AudioFeatures) -> str:
    code = camelot_code(features.key, features.mode)
    name = key_name(features.key)
    if code is None or name is None:
        return "no key"
    quality = "maj" if features.is_major() else "min"
    return f"{name} {quality} ({code})"


def describe_features(features: AudioFeatures) -> dict[str, object]:
    return {
        "track_id": features.track_id,
        "label": label_for(features),
        "camelot": camelot_code(features.key, features.mode),
        "tempo": features.tempo,
    }


def pitch_class_for_name(name: str) -> int:
    """Pitch class for a key name like ``"C"`` or ``"F#"``."""

    try:
        return KEY_NAMES.index(name)
    except ValueError as exc:
        raise ValueError(f"unknown key name: {name}") from exc


def code_quality(code: str) -> str:
    """``"maj"`` for a B-side Camelot code, ``"min"`` for an A-side one."""

    if code.endswith("B"):
        return "maj"
    if code.endswith("A"):
        return "min"
    raise ValueError(f"not a Camelot code: {code}")


def all_camelot_codes() -> list[str]:
    codes: list[str] = []
    for key in range(len(KEY_NAMES)):
        codes.append(f"{_CAMELOT_MAJOR[key]}B")
        codes.append(f"{_CAMELOT_MINOR[key]}A")
    return sorted(codes)


def label_many(features_list: list[AudioFeatures]) -> dict[str, str]:
    return {f.track_id: label_for(f) for f in features_list}

