from __future__ import annotations

"""Suggest harmonically compatible tracks to mix after a seed track."""

from dataclasses import dataclass

from audio_features import AudioFeatures
from harmonic_match import compatibility_reason, is_harmonically_compatible


def compatible_candidates(
    seed: AudioFeatures,
    candidates: list[AudioFeatures],
) -> list[AudioFeatures]:
    """Every candidate that is harmonically compatible with the seed."""

    return [c for c in candidates if is_harmonically_compatible(seed, c)]


def rank_by_tempo(seed: AudioFeatures, candidates: list[AudioFeatures]) -> list[AudioFeatures]:
    """Closest tempo first; ties broken by track id for determinism."""

    return sorted(candidates, key=lambda c: (abs(c.tempo - seed.tempo), c.track_id))


def recommend_next(
    seed: AudioFeatures,
    candidates: list[AudioFeatures],
    limit: int | None = None,
) -> list[AudioFeatures]:
    compatible = compatible_candidates(seed, candidates)
    ranked = rank_by_tempo(seed, compatible)
    if limit is not None:
        return ranked[:limit]
    return ranked


@dataclass
class HarmonicMixEngine:
    library: list[AudioFeatures]

    def suggest(self, seed: AudioFeatures, limit: int | None = None) -> list[AudioFeatures]:
        others = [f for f in self.library if f.track_id != seed.track_id]
        return recommend_next(seed, others, limit)

    def suggest_ids(self, seed: AudioFeatures, limit: int | None = None) -> list[str]:
        return [f.track_id for f in self.suggest(seed, limit)]

    def reasons(self, seed: AudioFeatures) -> dict[str, str]:
        others = [f for f in self.library if f.track_id != seed.track_id]
        return {f.track_id: compatibility_reason(seed, f) for f in others}

    def best_next(self, seed: AudioFeatures) -> AudioFeatures | None:
        ranked = self.suggest(seed, limit=1)
        return ranked[0] if ranked else None

    def has_any_match(self, seed: AudioFeatures) -> bool:
        return self.best_next(seed) is not None


def partition_by_compatibility(
    seed: AudioFeatures,
    candidates: list[AudioFeatures],
) -> tuple[list[AudioFeatures], list[AudioFeatures]]:
    """Split candidates into (compatible, incompatible), preserving order."""

    compatible: list[AudioFeatures] = []
    incompatible: list[AudioFeatures] = []
    for candidate in candidates:
        target = compatible if is_harmonically_compatible(seed, candidate) else incompatible
        target.append(candidate)
    return compatible, incompatible


def compatible_ids(seed: AudioFeatures, candidates: list[AudioFeatures]) -> list[str]:
    return [c.track_id for c in compatible_candidates(seed, candidates)]


def compatible_count(seed: AudioFeatures, candidates: list[AudioFeatures]) -> int:
    return len(compatible_candidates(seed, candidates))


def has_compatible(seed: AudioFeatures, candidates: list[AudioFeatures]) -> bool:
    return compatible_count(seed, candidates) > 0

