from __future__ import annotations

"""Decide whether two tracks are harmonically compatible for mixing.

Compatible keys, on the circle of fifths, are the same key (distance 0) or a
perfect fourth / perfect fifth apart. A fourth up and a fifth up are the same
move around a 12-note circle, so both land at a circular distance of 5
semitones. Mode (major vs minor) must match, and a track with no detected key
cannot be matched harmonically.
"""

from audio_features import AudioFeatures

# Circular semitone distances that count as harmonically compatible:
# 0 = same key, 5 = perfect fourth / perfect fifth (circle-of-fifths neighbor).
COMPATIBLE_DISTANCES = {0, 5}

PITCH_CLASSES = 12


def pitch_class_distance(a: int, b: int) -> int:
    """Distance in semitones between two pitch classes."""

    return abs(a - b)


def is_harmonically_compatible(seed: AudioFeatures, other: AudioFeatures) -> bool:
    """Whether ``other`` can be mixed in key with ``seed``."""

    if seed.mode != other.mode:
        return False
    return pitch_class_distance(seed.key, other.key) in COMPATIBLE_DISTANCES


def compatibility_reason(seed: AudioFeatures, other: AudioFeatures) -> str:
    if seed.mode != other.mode:
        return "mode_mismatch"
    distance = pitch_class_distance(seed.key, other.key)
    if distance == 0:
        return "same_key"
    if distance == 5:
        return "fifth_or_fourth"
    return "key_clash"


def distances_from(seed: AudioFeatures, others: list[AudioFeatures]) -> dict[str, int]:
    return {other.track_id: pitch_class_distance(seed.key, other.key) for other in others}


def count_compatible(seed: AudioFeatures, others: list[AudioFeatures]) -> int:
    return sum(1 for other in others if is_harmonically_compatible(seed, other))


def most_compatible(
    seed: AudioFeatures,
    others: list[AudioFeatures],
) -> AudioFeatures | None:
    """The compatible track closest in pitch class (ties broken by id)."""

    compatible = [o for o in others if is_harmonically_compatible(seed, o)]
    if not compatible:
        return None
    return min(
        compatible,
        key=lambda o: (pitch_class_distance(seed.key, o.key), o.track_id),
    )


def compatibility_matrix(tracks: list[AudioFeatures]) -> dict[tuple[str, str], bool]:
    """Pairwise compatibility for a set of tracks (excluding self-pairs)."""

    matrix: dict[tuple[str, str], bool] = {}
    for a in tracks:
        for b in tracks:
            if a.track_id == b.track_id:
                continue
            matrix[(a.track_id, b.track_id)] = is_harmonically_compatible(a, b)
    return matrix


def reason_counts(seed: AudioFeatures, others: list[AudioFeatures]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for other in others:
        reason = compatibility_reason(seed, other)
        counts[reason] = counts.get(reason, 0) + 1
    return counts

