from __future__ import annotations

"""Summarize a harmonic-match run for the DJ console."""

from audio_features import AudioFeatures
from camelot import label_for
from compatibility_engine import compatible_candidates
from harmonic_match import compatibility_reason


def summarize_matches(seed: AudioFeatures, candidates: list[AudioFeatures]) -> dict[str, object]:
    compatible = compatible_candidates(seed, candidates)
    return {
        "seed_id": seed.track_id,
        "seed_label": label_for(seed),
        "candidate_count": len(candidates),
        "compatible_count": len(compatible),
        "compatible_ids": [c.track_id for c in compatible],
    }


def reason_breakdown(seed: AudioFeatures, candidates: list[AudioFeatures]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for candidate in candidates:
        reason = compatibility_reason(seed, candidate)
        counts[reason] = counts.get(reason, 0) + 1
    return counts


def incompatible_candidates(
    seed: AudioFeatures,
    candidates: list[AudioFeatures],
) -> list[str]:
    compatible_ids = {c.track_id for c in compatible_candidates(seed, candidates)}
    return [c.track_id for c in candidates if c.track_id not in compatible_ids]


def atonal_candidates(candidates: list[AudioFeatures]) -> list[str]:
    return [c.track_id for c in candidates if not c.has_detected_key()]


def compatible_label_map(seed: AudioFeatures, candidates: list[AudioFeatures]) -> dict[str, str]:
    """Labels for the candidates that matched the seed."""

    return {c.track_id: label_for(c) for c in compatible_candidates(seed, candidates)}


def match_rate(seed: AudioFeatures, candidates: list[AudioFeatures]) -> float:
    if not candidates:
        return 0.0
    matched = len(compatible_candidates(seed, candidates))
    return matched / len(candidates)


def full_report(seed: AudioFeatures, candidates: list[AudioFeatures]) -> dict[str, object]:
    summary = summarize_matches(seed, candidates)
    summary["reason_breakdown"] = reason_breakdown(seed, candidates)
    summary["atonal_ids"] = atonal_candidates(candidates)
    summary["incompatible_ids"] = incompatible_candidates(seed, candidates)
    summary["match_rate"] = match_rate(seed, candidates)
    return summary


def has_atonal(candidates: list[AudioFeatures]) -> bool:
    return any(not c.has_detected_key() for c in candidates)


def compatible_label_lines(seed: AudioFeatures, candidates: list[AudioFeatures]) -> list[str]:
    """One ``"<id>: <label>"`` line per compatible candidate, for display."""

